def segments(cells):
    pts=set(cells); segs=[]
    # vertical segments: same column, contiguous rows
    from collections import defaultdict
    cols=defaultdict(list); rows=defaultdict(list)
    for i,j in pts: cols[j].append(i); rows[i].append(j)
    for j,ii in cols.items():
        ii=sorted(ii); run=[ii[0]]
        for a in ii[1:]:
            if a==run[-1]+1: run.append(a)
            else: segs.append(('V',j,run)); run=[a]
        segs.append(('V',j,run))
    for i,jj in rows.items():
        jj=sorted(jj); run=[jj[0]]
        for a in jj[1:]:
            if a==run[-1]+1: run.append(a)
            else: segs.append(('H',i,run)); run=[a]
        segs.append(('H',i,run))
    return segs

def f(grid):
    g=[r[:] for r in grid]; H,W=len(g),len(g[0])
    from collections import Counter
    bg=Counter(v for r in g for v in r).most_common(1)[0][0]
    pts=[(i,j) for i in range(H) for j in range(W) if g[i][j]!=bg]
    cc=Counter(g[i][j] for i,j in pts)
    scolor=min(cc,key=lambda c:cc[c])          # stray color = rarest non-bg
    strays=[(i,j) for i,j in pts if g[i][j]==scolor]
    segs=[s for s in segments([(i,j) for i,j in pts if g[i][j]!=scolor]) if len(s[2])>1]
    for si,sj in strays:
        # target segment: vertical whose rows contain stray row, or horizontal whose cols contain stray col
        tgt=[s for s in segs if (s[0]=='V' and s[2][0]<=si<=s[2][-1]) or (s[0]=='H' and s[2][0]<=sj<=s[2][-1])]
        others=[s for s in segs if s not in tgt]
        if tgt:
            t=tgt[0]
            if t[0]=='V':
                lo,hi=sorted((sj,t[1]))
                for j in range(lo+1,hi):
                    if g[si][j]==bg: g[si][j]=scolor
            else:
                lo,hi=sorted((si,t[1]))
                for i in range(lo+1,hi):
                    if g[i][sj]==bg: g[i][sj]=scolor
            # echo into other vertical segment's rows
            for o in others:
                if o[0]=='V' and t[0]=='V':
                    bidx=t[2].index(si)
                    if bidx<len(o[2]):
                        r=o[2][bidx]
                        for j in range(W):
                            if j!=o[1] and g[r][j]==bg: g[r][j]=scolor
        g[si][sj]=4
    return g

